	(63, 13, 'ELC00001', 'MCB ( Miniature Circuit Breaker ) Single phase', 'Breaking Capacity (kA) :  	     Ampere\nCurve Code :                                     C\nRated Operational Voltage (V) :	230\nNumber of Poles :                    	1P\nFrequency (Hz) :	                      50/60\nMagnetic Trip :                             5~10 x In\nMounting Mode :	                      Clip-on\nNetwork Type :                                  AC\nTrip Unit :	                               Thermal-magnetic\n\nMiniature Circuit Breaker ( MCB )\nHitungan untuk menentukan berapa ampere MCB yang akan dipasang\nI = V x P / I = V : A \nI = P x V = 900 VA : 220 volt = 4,09 Ampere.\nI = V x P = 4.09 A x 220 volt = 900 VA', '[{"id":"4","text":"MGS - Mahiera Global Solution"}]', '0', '[{"varian":"Ukuran","value":[{"id":"52","text":"2 A"},{"id":"53","text":"4 A"},{"id":"54","text":"6 A"},{"id":"55","text":"10 A"},{"id":"57","text":"16 A"},{"id":"58","text":"20 A"},{"id":"59","text":"25 A"},{"id":"64","text":"40 A"},{"id":"65","text":"50 A"},{"id":"66","text":"63 A"},{"id":"63","text":"32 A"}]},{"varian":"Type Phase","value":[{"id":"83","text":"1 phase"}]}]', '2025-02-18 10:27:08', 31),
