	(1, 'MGS', 'penawaran', '<ol><li data-list="ordered"><span class="ql-ui" contenteditable="false"></span>Penawaran ini bukan merupakan dokumen bukti transaksi pembelian <strong> </strong></li><li data-list="ordered"><span class="ql-ui" contenteditable="false"></span>Masa berlaku form penawaran selama 14 Hari terhitung dari tanggal dokumen ini dibuat</li></ol><p><br></p>', '{"ops":[{"insert":"Penawaran ini bukan merupakan dokumen bukti transaksi pembelian "},{"attributes":{"bold":"true"},"insert":" "},{"attributes":{"list":"ordered"},"insert":"\\n"},{"insert":"Masa berlaku form penawaran selama 14 Hari terhitung dari tanggal dokumen ini dibuat"},{"attributes":{"list":"ordered"},"insert":"\\n"},{"insert":"\\n"}]}'),
